import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";
import * as faceapi from "face-api.js";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [userId, setUserId] = useState("");
  const [qrData, setQrData] = useState("");
  const [photo, setPhoto] = useState("");
  const [paymentProof, setPaymentProof] = useState("");

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  /* FACE MODEL */
  useEffect(() => {
    const loadModels = async () => {
      await faceapi.nets.tinyFaceDetector.loadFromUri("/models");
    };
    loadModels();
  }, []);

  /* INPUT */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* PAYMENT SCREENSHOT */
  const handleFile = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();

    reader.onloadend = () => {
      setPaymentProof(reader.result);
    };

    if (file) reader.readAsDataURL(file);
  };

  /* REGISTER */
  const registerUser = async () => {
    try {
      const res = await axios.post("http://localhost:5000/register", {
        ...formData,
        photo,
        paymentProof,
      });

      if (res.data.success) {
        setUserId(res.data.userId);
        setQrData(res.data.qrData);
        alert("Registration Successful ✅");
      } else {
        alert(res.data.message);
      }
    } catch (err) {
      alert("Registration Failed ❌");
    }
  };

  /* CAMERA */
  const openCamera = async () => {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true });
    streamRef.current = stream;
    videoRef.current.srcObject = stream;
    videoRef.current.play();
  };

  const capturePhoto = async () => {
    const detections = await faceapi.detectAllFaces(
      videoRef.current,
      new faceapi.TinyFaceDetectorOptions()
    );

    if (detections.length !== 1) {
      alert("Only one face required ❌");
      return;
    }

    const canvas = canvasRef.current;
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;

    const ctx = canvas.getContext("2d");
    ctx.drawImage(videoRef.current, 0, 0);

    const image = canvas.toDataURL("image/png");
    setPhoto(image);

    streamRef.current.getTracks().forEach((track) => track.stop());
  };

  /* DOWNLOAD ID */
  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "ID_Card.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  return (
    <div>
      <Navbar />

      <div style={{ textAlign: "center", padding: "20px" }}>
        <h2>Event Registration</h2>

        {!qrData && (
          <>
            <input name="name" placeholder="Name" onChange={handleChange} /><br /><br />
            <input name="college_name" placeholder="College" onChange={handleChange} /><br /><br />
            <input name="phone" placeholder="Phone" onChange={handleChange} /><br /><br />
            <input name="email" placeholder="Email" onChange={handleChange} /><br /><br />

            <h3>Event: {eventName}</h3>

            {/* UPI SECTION */}
            <h3>Pay via GPay / UPI</h3>
            <p><b>UPI ID:</b> aswin9751@okaxis</p>

            <p>📸 Upload Payment Screenshot</p>
            <input type="file" onChange={handleFile} />

            <br /><br />
            <button onClick={registerUser}>
              Complete Registration
            </button>
          </>
        )}

        {qrData && (
          <div>
            <h3>Your QR Code</h3>
            <QRCode value={qrData.toString()} size={200} />

            <br /><br />
            <button onClick={openCamera}>Open Camera</button>

            <br /><br />
            <video ref={videoRef} width="320" height="240" />

            <br /><br />
            <button onClick={capturePhoto}>Capture</button>
            <canvas ref={canvasRef} style={{ display: "none" }} />
          </div>
        )}

        {photo && (
          <div>
            <div ref={idCardRef}>
              <h3>ID Card</h3>
              <p>Name: {formData.name}</p>
              <p>ID: {userId}</p>
              <p>Event: {eventName}</p>

              <QRCode value={qrData.toString()} size={120} />
              <img src={photo} width="120" />
            </div>

            <button onClick={downloadCard}>Download</button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Register;
